namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough
Mozzarella cheese
Fresh basil
Tomato sauce
Olive oil", Steps = "1. Preheat oven to 475°F
2. Roll out dough
3. Spread sauce and add cheese
4. Bake for 10-12 minutes
5. Top with fresh basil" },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti
Pancetta
Eggs
Parmesan cheese
Black pepper", Steps = "1. Cook spaghetti al dente
2. Fry pancetta until crispy
3. Mix eggs and parmesan
4. Toss hot pasta with pancetta
5. Stir in egg mixture off heat" },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken breast
Yogurt
Tomato puree
Garam masala
Cream
Onion
Garlic", Steps = "1. Marinate chicken in yogurt and spices
2. Grill chicken pieces
3. Sauté onion and garlic
4. Add tomato puree and spices
5. Simmer with cream and chicken" },
        new Recipe { Id = 4, Title = "Vegetable Pad Thai", Category = "Asian", Ingredients = "Rice noodles
Tofu
Bean sprouts
Peanuts
Lime
Fish sauce
Tamarind paste", Steps = "1. Soak rice noodles
2. Press and cube tofu
3. Make pad thai sauce
4. Stir-fry tofu and vegetables
5. Toss with noodles and sauce" },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef
Taco shells
Lettuce
Tomato
Cheddar cheese
Sour cream
Taco seasoning", Steps = "1. Brown beef with seasoning
2. Warm taco shells
3. Dice vegetables
4. Assemble tacos with toppings
5. Serve with lime wedges" },
        new Recipe { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados
Lime juice
Cilantro
Onion
Tomato
Jalapeño
Salt", Steps = "1. Mash avocados
2. Dice onion, tomato, jalapeño
3. Mix all ingredients
4. Season with salt and lime
5. Serve immediately" },
    };

    private readonly Dictionary<int, List<int>> _ratings = new();

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;
        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);

        var recipe = GetById(recipeId);
        if (recipe is not null)
        {
            recipe.RatingCount = _ratings[recipeId].Count;
            recipe.AverageRating = _ratings[recipeId].Average();
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }
}

