    protected override void OnInitialized()
    {
        Recipe = RecipeService.GetById(Id);
    }

    private static string StripNumberPrefix(string step)
    {
        var trimmed = step.TrimStart();
        if (trimmed.Length > 2 && char.IsDigit(trimmed[0]) && trimmed[1] == '.')
            return trimmed[2..].TrimStart();
        if (trimmed.Length > 3 && char.IsDigit(trimmed[0]) && char.IsDigit(trimmed[1]) && trimmed[2] == '.')
            return trimmed[3..].TrimStart();
        return trimmed;
    }
}

