<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= SelectedRating ? "selected" : "")"
              @onclick="() => Rate(star)"
              style="cursor:pointer; font-size:1.5rem; color: @(star <= SelectedRating ? "gold" : "#ccc")">
            ★
        </span>
    }
    @if (RatingCount > 0)
    {
        <span class="ms-2 text-muted">@CurrentRating.ToString("F1") avg (@RatingCount ratings)</span>
