+@page "/recipe/{Id:int}"
+
+<PageTitle>@(Recipe?.Title ?? "Recipe") - RecipeShare</PageTitle>
+
+@if (Recipe is not null)
+{
+    <h1>@Recipe.Title</h1>
+    <span class="badge bg-secondary">@Recipe.Category</span>
+
+    <h3 class="mt-4">Ingredients</h3>
+    <ul>
+        @foreach (var ingredient in Recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
+        {
+            <li>@ingredient</li>
+        }
+    </ul>
+
+    <h3>Steps</h3>
+    <ol>
+        @foreach (var step in Recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
+        {
+            <li>@StripNumberPrefix(step)</li>
+        }
+    </ol>
+
+    <h3>Rate this Recipe</h3>
+    <StarRating RecipeId="Recipe.Id" CurrentRating="Recipe.AverageRating" RatingCount="Recipe.RatingCount" />
+
+    <a href="category/@Recipe.Category" class="btn btn-secondary mt-3">← Back to @Recipe.Category</a>
+}
+else
+{
+    <p>Recipe not found.</p>
+    <a href="/" class="btn btn-secondary">← Back to Home</a>
+}
+
+@code {
+    [Parameter] public int Id { get; set; }
+    [Inject] private RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;
+
+    private RecipeShare.Models.Recipe? Recipe;
+
+    protected override void OnInitialized()
+    {
+        Recipe = RecipeService.GetById(Id);
+    }
+
+    private static string StripNumberPrefix(string step)
+    {
+        var trimmed = step.TrimStart();
+        if (trimmed.Length > 2 && char.IsDigit(trimmed[0]) && trimmed[1] == '.')
+            return trimmed[2..].TrimStart();
+        if (trimmed.Length > 3 && char.IsDigit(trimmed[0]) && char.IsDigit(trimmed[1]) && trimmed[2] == '.')
+            return trimmed[3..].TrimStart();
+        return trimmed;
+    }
+}
+

